import heapq
from collections import defaultdict

def toposort(nodes, edges):
    if not nodes:
        return []

    # Initialize in-degree and adjacency list without mutating inputs
    in_degree = {node: 0 for node in nodes}
    adj = defaultdict(set)

    # Process edges to build adjacency and count in-degrees (handling duplicates by set)
    for source, dest in edges:
        adj[source].add(dest)
        if dest in in_degree:
            in_degree[dest] += 1

    # Initialize heap with nodes having zero in-degree
    pq = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(pq)

    result = []

    while pq:
        node = heapq.heappop(pq)
        result.append(node)

        # Decrement in-degree for neighbors
        for neighbor in adj[node]:
            if neighbor in in_degree:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    heapq.heappush(pq, neighbor)

    # Check for cycle (if we processed fewer nodes than total)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected in graph")

    return result
